def send_telegram_notification(owner: str, repo: str, disc_number: int, title: str, author: str, comment_url: str):
    tg_token = os.environ.get("TELEGRAM_BOT_TOKEN", "").strip()
    tg_chat_id = os.environ.get("TELEGRAM_CHAT_ID", "").strip()
    if tg_token and tg_chat_id:
        try:
            tg_text = (
                f"🤖 *[Agente Centinela - {repo}]*\n\n"
                f"Se atendió la duda de @{author} en la Discusión #{disc_number}:\n"
                f"*{title}*\n\n"
                f"🔗 [Revisar y Validar Respuesta]({comment_url})"
            )
            tg_url = f"https://api.telegram.org/bot{tg_token}/sendMessage"
            payload = json.dumps({
                "chat_id": tg_chat_id,
                "text": tg_text,
                "parse_mode": "Markdown",
                "disable_web_page_preview": False
            }).encode("utf-8")
            req = urllib.request.Request(tg_url, data=payload, headers={"Content-Type": "application/json"}, method="POST")
            with urllib.request.urlopen(req, timeout=10) as resp:
                if resp.status == 200:
                    log("Notificación Nivel 3 (Telegram) despachada con éxito.")
        except Exception as e:
            log(f"Aviso al enviar alerta a Telegram: {e}")


