def gather_repository_context() -> Dict[str, Any]:
    """Extrae el estado vivo del repositorio para alimentar el contexto del agente."""
    context: Dict[str, Any] = {
        "stack": "TanStack Start / React 19 / Vite 8 / Tailwind CSS v4",
        "arquitectura": "Generación Estática (SSG) desplegada en GitHub Pages sin backend persistente",
        "habilidades": ["01-definir", "02-planificar", "03-construir", "04-verificar", "05-revisar", "06-aprobar", "07-centinela"],
        "seguridad": "Secretos en GitHub Secrets; escaneo con gitleaks; cero credenciales en bundle de cliente",
        "proyectos_destacados": [
            "QR Voxel Studio (procesamiento local QR, WebGL/Three.js, escenas voxel)",
            "AussieCare (PWA educativa offline-first, Service Worker)",
            "Bio-Gesture Control Android (MediaPipe visión artificial, transformación de coordenadas, Android Accessibility)",
            "KASA Service Tracker (.NET 8, persistencia JSON, trazabilidad, exportación XLSX)",
            "Tlalne-Priority (C++20, cola de prioridad, índice por folio, persistencia CSV)",
            "Dev Visualizer (atlas técnico interactivo, manifiesto central y escenas accesibles)"
        ],
        "identidad_visual": "Paleta Arcane (azul profundo, cian, rosa, magenta), 22 sprites transparentes de grafitis de Jinx y ancla con monograma 'L'"
    }

    for pkg_path in ["portfolio-source/package.json", "../portfolio-source/package.json", "package.json"]:
        if os.path.isfile(pkg_path):
            try:
                with open(pkg_path, "r", encoding="utf-8") as f:
                    pkg = json.load(f)
                    context["dependencies"] = list(pkg.get("dependencies", {}).keys())
                    context["devDependencies"] = list(pkg.get("devDependencies", {}).keys())
                    break
            except Exception as e:
                log(f"Aviso al leer {pkg_path}: {e}")

    try:
        log_out = run_cmd(["git", "log", "-n", "3", "--oneline"], check=False)
        if log_out:
            context["ultimos_commits"] = log_out.splitlines()
    except Exception:
        pass

    return context


def get_discussion_details(owner: str, repo: str, number: int) -> Dict[str, Any]:
    """Obtiene los detalles y comentarios de una discusión específica."""
    query = """
    query($owner: String!, $name: String!, $num: Int!) {
      repository(owner: $owner, name: $name) {
        discussion(number: $num) {
          id
          number
          title
          body
          url
          createdAt
          author {
            login
          }
          answer {
            id
          }
          category {
            id
            name
            isAnswerable
          }
          comments(last: 20) {
            totalCount
            nodes {
              id
              author {
                login
              }
              body
              createdAt
            }
          }
        }
      }
    }
    """
    res = gh_graphql(query, {"owner": owner, "name": repo, "num": number})
    discussion = res.get("repository", {}).get("discussion")
    if not discussion:
        raise ValueError(f"No se encontró la discusión #{number} en {owner}/{repo}")
    return discussion


def get_open_discussions(owner: str, repo: str, limit: int = 10) -> List[Dict[str, Any]]:
    """Obtiene las discusiones recientes para auditar cuáles requieren respuesta."""
    query = """
    query($owner: String!, $name: String!, $limit: Int!) {
      repository(owner: $owner, name: $name) {
        discussions(first: $limit, orderBy: {field: UPDATED_AT, direction: DESC}) {
          nodes {
            id
            number
            title
            body
            url
            createdAt
            author {
              login
            }
            answer {
              id
            }
            category {
              id
              name
              isAnswerable
            }
            comments(last: 10) {
              totalCount
              nodes {
                id
                author {
                  login
                }
                body
                createdAt
              }
            }
          }
        }
      }
    }
    """
    res = gh_graphql(query, {"owner": owner, "name": repo, "limit": limit})
    return res.get("repository", {}).get("discussions", {}).get("nodes", [])


def needs_response(discussion: Dict[str, Any], force: bool = False) -> Optional[Dict[str, Any]]:
    """
    Evalúa si la discusión o un hilo continuado tiene preguntas sin responder.
    Retorna el comentario o nodo al que se debe responder, o None si ya está atendida.
    """
    comments = discussion.get("comments", {}).get("nodes", [])

    if force:
        return comments[-1] if comments else {"body": discussion.get("body", ""), "author": discussion.get("author")}

    if not comments:
        disc_author = discussion.get("author", {}).get("login", "")
        if disc_author and disc_author != OWNER_DEFAULT:
            return {"body": discussion.get("body", ""), "author": discussion.get("author")}
        return None

    last_comment = comments[-1]
    last_author = last_comment.get("author", {}).get("login", "")
    last_body = last_comment.get("body", "")

    if SIGNATURE_MARKER in last_body or SIGNATURE_MARKER_EN in last_body:
        return None

    if last_author == OWNER_DEFAULT:
        return None

    return last_comment


# -----------------------------------------------------------------------------
# INVOCACIÓN A GEMINI API (MODELOS ACTUALIZADOS Y DIAGNÓSTICO)
# -----------------------------------------------------------------------------

def call_gemini_api(prompt: str, api_key: str) -> Optional[str]:
    """Invoca la API de Gemini utilizando modelos actualizados y encabezados oficiales con diagnóstico."""
    models = ["gemini-3.8-flash", "gemini-2.5-flash", "gemini-2.0-flash", "gemini-1.5-flash"]
    endpoints = [
        "https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent",
        "https://generativelanguage.googleapis.com/v1/models/{model}:generateContent"
    ]

    for model in models:
        for ep_template in endpoints:
            url = ep_template.format(model=model) + f"?key={api_key}"
            payload = {
                "contents": [{"parts": [{"text": prompt}]}],
                "generationConfig": {
                    "temperature": 0.25,
                    "maxOutputTokens": 2048,
                }
            }
            data = json.dumps(payload).encode("utf-8")
            headers = {
                "Content-Type": "application/json",
                "x-goog-api-key": api_key
            }
            req = urllib.request.Request(url, data=data, headers=headers)
            try:
                with urllib.request.urlopen(req, timeout=25) as resp:
                    if resp.status == 200:
                        res_body = json.loads(resp.read().decode("utf-8"))
                        candidates = res_body.get("candidates", [])
                        if candidates:
                            text = candidates[0].get("content", {}).get("parts", [{}])[0].get("text", "")
                            if text:
                                log(f"Gemini API generó respuesta con éxito usando modelo {model}.")
                                return text.strip()
            except urllib.error.HTTPError as he:
                error_body = ""
                try:
                    error_body = he.read().decode("utf-8")
                except Exception:
                    pass
                log(f"Diagnóstico Gemini API ({model} - {he.code} {he.reason}): {error_body[:250]}")
                continue
            except Exception as e:
                log(f"Aviso de conexión con modelo {model} en Gemini API: {e}")
                continue
    return None


